UPDATE tenant_quota
SET used_token_count = used_token_count + #{tokens}
WHERE tenant_id = #{tenantId}
  AND used_token_count + #{tokens} <= daily_token_limit

UPDATE tenant_quota
SET used_upload_count = 0,
    used_token_count = 0,
    reset_time = #{nextResetTime}
WHERE tenant_id = #{tenantId}
